const getServicePriceDistribution = `-- name: GetServicePriceDistribution :many
SELECT 
    CASE
        WHEN cost = 0 OR cost IS NULL THEN 'Free'
        WHEN cost < 500 THEN 'Under R500'
        WHEN cost < 1000 THEN 'R500-R1000'
        WHEN cost < 2000 THEN 'R1000-R2000'
        ELSE 'Over R2000'
    END as price_range,
    COUNT(*) as count,
    AVG(average_rating) FILTER (WHERE average_rating IS NOT NULL) as avg_rating
FROM clinic_services
WHERE 
    clinic_id = $1
    AND is_active = TRUE
GROUP BY price_range
ORDER BY 
    CASE price_range
        WHEN 'Free' THEN 1
        WHEN 'Under R500' THEN 2
        WHEN 'R500-R1000' THEN 3
        WHEN 'R1000-R2000' THEN 4
        ELSE 5
    END
`

type GetServicePriceDistributionRow struct {
	PriceRange string  `json:"price_range"`
	Count      int64   `json:"count"`
	AvgRating  float64 `json:"avg_rating"`
}

func (q *Queries) GetServicePriceDistribution(ctx context.Context, clinicID pgtype.UUID) ([]GetServicePriceDistributionRow, error) {
	rows, err := q.db.Query(ctx, getServicePriceDistribution, clinicID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GetServicePriceDistributionRow{}
	for rows.Next() {
		var i GetServicePriceDistributionRow
		if err := rows.Scan(&i.PriceRange, &i.Count, &i.AvgRating); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

